// Agoda — shoot the planes (a reported variant of LeetCode 1921, Eliminate Maximum Number of Monsters).
public static class Planes {
    // Plane i is dist[i] above the ground, descending at speed[i] per second. You fire at t = 0, 1, 2, …
    // (shotsPerSecond shots each second). A plane that reaches the ground at or before the moment you would
    // fire at it ends the game. Return how many planes you shoot before that happens.
    public static int MaxShot(int[] dist, int[] speed) => MaxShot(dist, speed, 1);

    public static int MaxShot(int[] dist, int[] speed, int shotsPerSecond) {
        if (dist == null || speed == null) return 0;
        if (dist.Length != speed.Length) throw new ArgumentException("dist and speed must have the same length");
        if (shotsPerSecond <= 0) throw new ArgumentOutOfRangeException(nameof(shotsPerSecond));
        int n = dist.Length;
        // Arrival second, rounded up: firing at integer second t beats plane i exactly when t < ceil(dist/speed).
        // Arrivals beyond n seconds never matter, so a counting sort keeps this O(n).
        var count = new int[n + 1];
        for (int i = 0; i < n; i++) {
            if (speed[i] <= 0) throw new ArgumentOutOfRangeException(nameof(speed), "speeds must be positive");
            if (dist[i] < 0) throw new ArgumentOutOfRangeException(nameof(dist), "distances must be non-negative");
            long arrive = ((long)dist[i] + speed[i] - 1) / speed[i];
            count[(int)Math.Min(arrive, n)]++;
        }
        int shot = 0;
        for (int t = 0; t <= n && shot < n; t++) {
            for (int c = 0; c < count[t]; c++) {
                // the shot-th plane in arrival order is fired on at second shot / shotsPerSecond
                if (t <= shot / shotsPerSecond) return shot;
                shot++;
            }
        }
        return shot;
    }
}
